# apia-p1-battery - post-leakfix paper-1 rerun on Kaggle CPU.
# Repo modules registered in sys.modules (causal-ordering fix) +
# saturation/valve/clamp drivers in isolated namespaces.
# Outputs -> /kaggle/working.
import json
import os
import sys
import types
import numpy as np
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt


def _mkmod(name, src):
    m = types.ModuleType(name)
    m.__file__ = name + '.py'
    exec(compile(src, m.__file__, 'exec'), m.__dict__)
    sys.modules[name] = m
    return m


RESERVOIR_SRC = '"""\nAPIA 2.0 Research Prototype\nModule: reservoir.py\nPurpose: manage Echo State Network (ESN) reservoir dynamics with a\n         strict mathematical ESP (Echo State Property) guarantee.\n"""\n\nimport numpy as np\nimport scipy.sparse as sp\nfrom scipy.sparse.linalg import norm as sparse_norm\n\n# Dimension limit below which the exact spectral norm is computed via\n# dense SVD; above it, iterative svds is used (approximate result).\nDENSE_SVD_LIMIT = 2048\n\n\nclass ReservoirEngine:\n    def __init__(self, input_dim: int, reservoir_size: int,\n                 sparsity: float = 0.1, leakage_rate: float = 0.3,\n                 input_scaling: float = 1.0, seed: int = 42):\n        """\n        :param input_dim: size of the input vector (e.g. lagged history L)\n        :param reservoir_size: number of reservoir neurons (D)\n        :param sparsity: nonzero fraction in the W_res matrix\n        :param leakage_rate: alpha (leak rate). 0 < alpha <= 1\n        :param input_scaling: amplitude scale of the W_in matrix\n        :param seed: random seed for reproducibility\n        """\n        if not (0.0 < leakage_rate <= 1.0):\n            raise ValueError(f"leakage_rate must be in (0, 1], got {leakage_rate}")\n        if not (0.0 < sparsity <= 1.0):\n            raise ValueError(f"sparsity must be in (0, 1], got {sparsity}")\n\n        self.input_dim = input_dim\n        self.reservoir_size = reservoir_size\n        self.sparsity = sparsity\n        self.alpha = leakage_rate\n        self.input_scaling = input_scaling\n        self.seed = seed\n\n        # Module-local RNG: does not pollute global np.random state.\n        self.rng = np.random.default_rng(self.seed)\n\n        # 1. W_in: input weights, drawn uniform on [-1, 1] and scaled.\n        self.W_in = self.rng.uniform(\n            -1.0, 1.0, (reservoir_size, input_dim)) * self.input_scaling\n\n        # 2. W_res: reservoir weights (sparse matrix)\n        self.W_res = self._generate_sparse_reservoir_matrix()\n\n        # 3. ESP guarantee: (1 - alpha) + alpha * ||W_res||_2 < 1\n        self._enforce_esp_condition()\n\n        # Initial state (zero vector)\n        self.state = np.zeros(reservoir_size)\n\n    def _generate_sparse_reservoir_matrix(self) -> sp.csr_matrix:\n        """\n        Builds a random reservoir weight matrix with the given sparsity;\n        entries lie in [-1, 1].\n\n        IMPORTANT: replace=False samples unique (row, col) pairs.\n        Generating indices with np.random.randint leads to duplicate\n        indices that csr_matrix SUMS together, which both reduces the\n        effective sparsity and pushes entries outside [-1, 1].\n        """\n        total_elements = self.reservoir_size * self.reservoir_size\n        num_nonzero = int(total_elements * self.sparsity)\n\n        flat_idx = self.rng.choice(total_elements, size=num_nonzero,\n                                   replace=False)\n        rows, cols = np.divmod(flat_idx, self.reservoir_size)\n        data = self.rng.uniform(-1.0, 1.0, num_nonzero)\n\n        return sp.csr_matrix(\n            (data, (rows, cols)),\n            shape=(self.reservoir_size, self.reservoir_size))\n\n    def _spectral_norm(self) -> float:\n        """||W_res||_2: exact SVD for small matrices, svds for large."""\n        if self.reservoir_size <= DENSE_SVD_LIMIT:\n            return float(np.linalg.svd(\n                self.W_res.toarray(), compute_uv=False)[0])\n        return float(sparse_norm(self.W_res, ord=2))\n\n    def _enforce_esp_condition(self):\n        """\n        Sufficient condition for ESP (contraction map):\n            ||dF/dx|| <= (1 - alpha) + alpha * ||W_res||_2 < 1\n        This bound is valid because tanh has Lipschitz constant 1.\n        Scales W_res until the condition holds.\n        """\n        current_norm = self._spectral_norm()\n\n        # Target: (1 - alpha) + alpha * target_norm <= 0.99\n        #         (0.99 = safety margin for the strict inequality)\n        # => target_norm <= (alpha - 0.01) / alpha\n        target_norm = (self.alpha - 0.01) / self.alpha\n\n        if target_norm <= 0:\n            raise ValueError(\n                f"Leakage rate (alpha={self.alpha}) too small to "\n                "guarantee ESP with margin.")\n\n        if current_norm > target_norm:\n            if current_norm == 0.0:\n                raise ValueError("W_res is degenerate (zero norm).")\n            scaling_factor = target_norm / current_norm\n            self.W_res = self.W_res * scaling_factor\n            print(f"[INFO] W_res scaled by {scaling_factor:.4f} "\n                  "to enforce ESP condition.")\n            print(f"       New ||W_res||_2 = {self._spectral_norm():.4f}")\n        else:\n            print(f"[INFO] ESP condition naturally satisfied. "\n                  f"||W_res||_2 = {current_norm:.4f}")\n\n    def step(self, u: np.ndarray) -> np.ndarray:\n        """\n        Advances the reservoir state by one time step.\n        x_t = (1 - alpha) * x_{t-1} + alpha * tanh(W_res @ x_{t-1} + W_in @ u_t)\n\n        :param u: input vector (input_dim,)\n        :return: updated reservoir state (reservoir_size,)\n        """\n        u = np.asarray(u, dtype=float)\n        if u.shape[0] != self.input_dim:\n            raise ValueError(\n                f"Input dimension mismatch. Expected {self.input_dim}, "\n                f"got {u.shape[0]}")\n\n        activated = np.tanh(self.W_res.dot(self.state) + self.W_in.dot(u))\n        self.state = (1.0 - self.alpha) * self.state + self.alpha * activated\n\n        return self.state.copy()\n\n    def get_state(self) -> np.ndarray:\n        """Returns the current reservoir state."""\n        return self.state.copy()\n\n    def reset(self):\n        """Resets the reservoir state to zero."""\n        self.state = np.zeros(self.reservoir_size)\n\n    def validate_esp_empirical(self, num_steps: int = 500,\n                               num_trials: int = 5,\n                               tol: float = 1e-4,\n                               seed: int = 99) -> bool:\n        """\n        Empirical ESP validation: starts num_trials pairs of different\n        initial states, feeds the same input sequence, and checks whether\n        the states converge. Does NOT touch the engine\'s own state or the\n        global RNG; works entirely with local variables.\n\n        :return: True if max distance < tol across all trials\n        """\n        rng = np.random.default_rng(seed)\n        inputs = rng.uniform(-1.0, 1.0, (num_steps, self.input_dim))\n\n        max_dist = 0.0\n        for _ in range(num_trials):\n            state1 = rng.uniform(-1.0, 1.0, self.reservoir_size)\n            state2 = rng.uniform(-1.0, 1.0, self.reservoir_size)\n\n            for u in inputs:\n                state1 = ((1.0 - self.alpha) * state1\n                          + self.alpha * np.tanh(\n                              self.W_res.dot(state1) + self.W_in.dot(u)))\n                state2 = ((1.0 - self.alpha) * state2\n                          + self.alpha * np.tanh(\n                              self.W_res.dot(state2) + self.W_in.dot(u)))\n\n            max_dist = max(max_dist, float(np.linalg.norm(state1 - state2)))\n\n        print(f"[VALIDATION] Empirical ESP max distance over {num_trials} "\n              f"trials after {num_steps} steps: {max_dist:.6e}")\n        return max_dist < tol\n\n\n# ==========================================\n# TEST BLOCK (verifies module correctness)\n# ==========================================\n'
_mkmod('reservoir', RESERVOIR_SRC)

RLS_ENGINE_SRC = '"""\nAPIA 2.0 Research Prototype\nModule: rls_engine.py\nPurpose: map the reservoir state (x_t) to a GAM-style spline feature\n      map (phi) and train a LINEAR readout on those features.\n      Three methods are compared:\n        (a) Batch Ridge Regression  -> O(N*F^2) training cost, offline\n        (b) Full RLS                -> O(F^2) = O(D^2 K^2) per step\n        (c) Block-Diagonal RLS      -> O(D*K^2) per step (~100x savings)\n\n      Key point: a single-layer spline expansion + linear readout is\n      linear in the weights, so it can be solved in CLOSED FORM by\n      RLS/ridge. No "Hebbian" update is needed; RLS is the proven\n      online algorithm that converges to the ridge solution.\n"""\n\nimport numpy as np\nimport time\n\n\n# ============================================================\n# 1. SPLINE FEATURE MAP (GAM-style, fixed basis)\n# ============================================================\nclass SplineFeatureMap:\n    """\n    Computes K B-spline basis functions per input component x_j over an\n    open-uniform knot vector.\n\n    phi(x) = [B(x_1), B(x_2), ..., B(x_D), 1.0]  in  R^{D*K + 1}\n\n    The basis functions are FIXED (knots are not learned); only the\n    readout coefficients are learned. This is the "KAN-inspired basis\n    expansion + linear solve" approach in the spirit of KARC/HKAN.\n    """\n\n    def __init__(self, input_dim: int, n_basis: int = 10, degree: int = 3,\n                 lo: float = -1.0, hi: float = 1.0):\n        if n_basis < degree + 1:\n            raise ValueError(\n                f"n_basis ({n_basis}) must be >= degree+1 ({degree+1})")\n        self.input_dim = input_dim\n        self.n_basis = n_basis\n        self.degree = degree\n        self.lo, self.hi = lo, hi\n\n        # Open-uniform knot vector: endpoints repeated degree+1 times.\n        n_interior = n_basis - degree - 1\n        interior = (np.linspace(lo, hi, n_interior + 2)[1:-1]\n                    if n_interior > 0 else np.empty(0))\n        self.knots = np.concatenate([\n            np.full(degree + 1, lo), interior, np.full(degree + 1, hi)])\n        # len(knots) = n_basis + degree + 1  (check)\n        assert len(self.knots) == n_basis + degree + 1\n\n        self.n_features = input_dim * n_basis + 1  # +1: bias\n\n    def _basis_matrix(self, x: np.ndarray) -> np.ndarray:\n        """Cox-de Boor: x (n,) -> basis values (n, n_basis)."""\n        t = self.knots\n        x = np.clip(np.asarray(x, dtype=float), t[0], t[-1])\n        n = x.size\n\n        # Degree 0: write 1 into the supporting interval of each x\n        B = np.zeros((n, len(t) - 1))\n        idx = np.clip(np.searchsorted(t, x, side=\'right\') - 1,\n                      0, len(t) - 2)\n        B[np.arange(n), idx] = 1.0\n\n        for d in range(1, self.degree + 1):\n            nb = len(t) - d - 1\n            # Left term: (x - t_i)/(t_{i+d} - t_i) * B_{i,d-1}\n            dl = t[d:d + nb] - t[:nb]\n            left = np.divide(\n                x[:, None] - t[:nb][None, :],\n                np.broadcast_to(dl[None, :], (n, nb)),\n                out=np.zeros((n, nb)), where=(dl[None, :] > 0)\n            ) * B[:, :nb]\n            # Right term: (t_{i+d+1} - x)/(t_{i+d+1} - t_{i+1}) * B_{i+1,d-1}\n            dr = t[d + 1:d + 1 + nb] - t[1:nb + 1]\n            right = np.divide(\n                t[d + 1:d + 1 + nb][None, :] - x[:, None],\n                np.broadcast_to(dr[None, :], (n, nb)),\n                out=np.zeros((n, nb)), where=(dr[None, :] > 0)\n            ) * B[:, 1:nb + 1]\n            B = left + right\n\n        # Right endpoint (x == hi): the last basis function equals 1\n        edge = x >= t[-1]\n        if np.any(edge):\n            B[edge] = 0.0\n            B[edge, -1] = 1.0\n        return B\n\n    def transform(self, x: np.ndarray) -> np.ndarray:\n        """x (D,) -> phi (D*K + 1,). Block layout: phi[j*K:(j+1)*K] = B(x_j)."""\n        x = np.asarray(x, dtype=float)\n        if x.shape[0] != self.input_dim:\n            raise ValueError(f"Expected dim {self.input_dim}, "\n                             f"got {x.shape[0]}")\n        phi = self._basis_matrix(x).reshape(-1)\n        return np.append(phi, 1.0)\n\n\n# ============================================================\n# 2. READOUT METHODS\n# ============================================================\nclass RidgeReadout:\n    """Batch ridge regression: W = (Phi^T Phi + lam I)^{-1} Phi^T Y."""\n\n    def __init__(self, n_features: int, n_outputs: int):\n        self.W = np.zeros((n_features, n_outputs))\n\n    def fit(self, Phi: np.ndarray, Y: np.ndarray, lam: float = 1e-4):\n        A = Phi.T @ Phi + lam * np.eye(Phi.shape[1])\n        self.W = np.linalg.solve(A, Phi.T @ Y)\n        return self\n\n    def predict(self, phi: np.ndarray) -> np.ndarray:\n        return phi @ self.W\n\n\nclass FullRLS:\n    """\n    Standard RLS with forgetting factor.\n    Per-step cost: O(F^2) = O(D^2 K^2). Memory: F^2.\n    P0 = init_var * I  (large init_var = weak prior confidence)\n    Choosing lam < 1 gives exponential forgetting for continual learning.\n    """\n\n    def __init__(self, n_features: int, n_outputs: int,\n                 forgetting: float = 1.0, init_var: float = 1e2,\n                 windup_mult: float = None):\n        self.W = np.zeros((n_features, n_outputs))\n        self.P = np.eye(n_features) * init_var\n        self.lam = forgetting\n        self._step = 0\n        # Covariance windup bound: if trace(P) exceeds this threshold,\n        # P is softly scaled down (eigenvalue structure preserved).\n        # None = unbounded.\n        self.trace_bound = (init_var * n_features * windup_mult\n                            if windup_mult is not None else None)\n\n    def update(self, phi: np.ndarray, y: np.ndarray):\n        phiP = phi @ self.P                      # (F,) - the only O(F^2)\n        # matvec; P is symmetric so P@phi == phiP.T (no second matvec).\n        s = self.lam + phiP @ phi\n        g = phiP / s\n        e = y - phi @ self.W                     # prediction error (predict first)\n        self.W += np.outer(g, e)\n        self.P -= np.outer(g, phiP)              # O(F^2)\n        self.P /= self.lam\n        # P-BOUNDING: with lam<1 the trace in dead directions grows like\n        # lam^-t; if the threshold is crossed, softly rescale (not reset).\n        if self.trace_bound is not None:\n            tr = np.trace(self.P)\n            if tr > self.trace_bound:\n                self.P *= self.trace_bound / tr\n        # Numerical symmetry drift accumulates slowly; maintenance every\n        # 64 steps is sufficient.\n        self._step += 1\n        if self._step % 64 == 0:\n            self.P = 0.5 * (self.P + self.P.T)\n        return e\n\n    def predict(self, phi: np.ndarray) -> np.ndarray:\n        return phi @ self.W\n\n\nclass BlockDiagRLS:\n    """\n    Block-diagonal RLS approximation: instead of a full P (F x F), a\n    separate P_j (K x K) is kept per input component j (+ scalar bias\n    block).\n\n      s = lam + sum_j phi_j^T P_j phi_j  (+ P_bias)\n      g_j = P_j phi_j / s\n      W_j += g_j e^T ;  P_j = (P_j - g_j (P_j phi_j)^T) / lam\n\n    Per-step cost: O(D*K^2). Memory: D*K^2.\n    D=100, K=10 -> ~100x fewer operations and memory than full RLS.\n    """\n\n    def __init__(self, input_dim: int, n_basis: int, n_outputs: int,\n                 forgetting: float = 1.0, init_var: float = 1e2,\n                 windup_mult: float = None):\n        self.D, self.K = input_dim, n_basis\n        self.n_features = input_dim * n_basis + 1\n        self.W = np.zeros((self.n_features, n_outputs))\n        self.P_blocks = np.tile(\n            np.eye(n_basis) * init_var, (input_dim, 1, 1))\n        self.P_bias = np.array([[init_var]])\n        self.lam = forgetting\n        # Per-block trace bound: stops dead-direction windup with an\n        # O(K) check.\n        self.trace_bound = (init_var * n_basis * windup_mult\n                            if windup_mult is not None else None)\n        self._bias_bound = (init_var * windup_mult\n                            if windup_mult is not None else None)\n\n    def update(self, phi: np.ndarray, y: np.ndarray):\n        phi_b = phi[:self.D * self.K].reshape(self.D, self.K)\n        pb = phi[-1]  # bias feature (=1.0)\n\n        Q = np.einsum(\'dij,dj->di\', self.P_blocks, phi_b)  # (D,K) O(DK^2)\n        s = self.lam + np.sum(phi_b * Q) + self.P_bias[0, 0] * pb * pb\n\n        e = y - phi @ self.W\n\n        G = Q / s\n        self.W[:self.D * self.K] += (G.reshape(-1, 1)) * e[None, :]\n        self.P_blocks -= np.einsum(\'di,dj->dij\', G, Q)\n        self.P_blocks /= self.lam\n\n        # P-BOUNDING (soft): blocks exceeding the trace threshold are\n        # rescaled; eigenvalue structure preserved, O(K) check cost.\n        if self.trace_bound is not None:\n            tr = np.einsum(\'dii->d\', self.P_blocks)\n            over = tr > self.trace_bound\n            if np.any(over):\n                self.P_blocks[over] *= (self.trace_bound\n                                        / tr[over])[:, None, None]\n\n        g_b = self.P_bias[0, 0] * pb / s\n        self.W[-1] += g_b * e\n        self.P_bias = (self.P_bias - np.array([[g_b * self.P_bias[0, 0] * pb]])) / self.lam\n        if self._bias_bound is not None and self.P_bias[0, 0] > self._bias_bound:\n            self.P_bias[0, 0] = self._bias_bound\n        return e\n\n    def predict(self, phi: np.ndarray) -> np.ndarray:\n        return phi @ self.W\n\n    # ---- Memory-transfer interface (for memory.py) ----\n    def get_weights(self) -> np.ndarray:\n        return self.W.copy()\n\n    def set_weights(self, W: np.ndarray):\n        self.W = np.asarray(W, dtype=float).copy()\n\n    def inflate_P(self, factor: float):\n        """Reopens plasticity by inflating P after consolidation."""\n        self.P_blocks *= factor\n        self.P_bias *= factor\n\n\n# ============================================================\n# 3. METRICS AND DATA GENERATION\n# ============================================================\ndef nmse(y_true: np.ndarray, y_pred: np.ndarray) -> float:\n    """Normalized MSE: ||y - yhat||^2 / ||y - mean(y)||^2  (1.0 = mean predictor)"""\n    num = np.sum((y_true - y_pred) ** 2)\n    den = np.sum((y_true - np.mean(y_true, axis=0)) ** 2)\n    return float(num / den)\n\n\ndef mackey_glass(n: int, tau: int = 17, beta: float = 0.2,\n                 gamma: float = 0.1, seed: int = 0) -> np.ndarray:\n    """Standard RC benchmark: Mackey-Glass tau=17 series (Euler, dt=1)."""\n    rng = np.random.default_rng(seed)\n    x = np.full(n + tau, 1.2) + 0.01 * rng.standard_normal(n + tau)\n    for t in range(tau, n + tau - 1):\n        x[t + 1] = (x[t] - gamma * x[t]\n                    + beta * x[t - tau] / (1.0 + x[t - tau] ** 10))\n    return x[tau:]\n\n\n# ============================================================\n# 4. COMPARISON PROTOCOL (Mackey-Glass 1-step prediction)\n# ============================================================\n'
_mkmod('rls_engine', RLS_ENGINE_SRC)

MEMORY_SRC = '"""\nAPIA 2.0 Research Prototype\nModule: memory.py\nPurpose: dual-rate memory mechanism (W_fast / W_slow) — analytic and\n      DISCONTINUITY-FREE consolidation.\n\nPrediction model:\n      y_hat = phi\' @ W_fast + beta * phi\' @ W_slow\n\nConsolidation rule (continuity guaranteed, y_hat unchanged):\n      W_slow <- W_slow + (1-gamma)/beta * W_fast\n      W_fast <- gamma * W_fast\n\n  Check:   gW_f + b(W_s + (1-g)/b W_f) = gW_f + bW_s + (1-g)W_f\n          = W_f + bW_s  (same as before)  => NO jump discontinuity.\n\nDouble-counting prevention:\n      The RESIDUAL is used as the W_fast training target:\n          e = y - (phi\'W_fast + beta*phi\'W_slow)\n      so W_fast does not relearn the signal W_slow already explains.\n      Implementation: the model is fed the target (y - beta*phi\'W_slow);\n      the engine\'s internal error already equals the total prediction\n      error.\n\nWindup interaction:\n      This layer requires trace-bounding together with lambda<1\n      (rls_engine windup_mult). In addition, P is slightly inflated at\n      consolidation to compensate for the damped W_fast (plasticity\n      is reopened).\n"""\n\nimport numpy as np\n\n\nclass DualMemory:\n    """\n    Wraps a dual-rate memory around BlockDiagRLS (or any engine with a\n    get/set_weights + inflate_P interface).\n    """\n\n    def __init__(self, model, beta: float = 1.0, gamma: float = 0.1,\n                 consolidate_every: int = 250, p_inflate: float = 1.5):\n        """\n        :param model: RLS engine with get_weights/set_weights/inflate_P\n        :param beta: gain of W_slow\'s contribution to prediction\n        :param gamma: fraction of W_fast retained at consolidation (0<g<=1)\n        :param consolidate_every: steps between consolidations\n        :param p_inflate: P inflation factor at consolidation (1.0 = off)\n        """\n        if not (0.0 < gamma <= 1.0):\n            raise ValueError(f"gamma must be in (0,1], got {gamma}")\n        if beta == 0.0:\n            raise ValueError("beta must be nonzero")\n        self.model = model\n        self.beta = beta\n        self.gamma = gamma\n        self.consolidate_every = consolidate_every\n        self.p_inflate = p_inflate\n\n        self.W_slow = np.zeros_like(model.get_weights())\n        self._steps = 0\n        self.n_consolidations = 0\n        # For validation: prediction-continuity deviation at consolidation\n        self.max_discontinuity = 0.0\n\n    def _slow_part(self, phi: np.ndarray) -> np.ndarray:\n        return self.beta * (phi @ self.W_slow)\n\n    def predict(self, phi: np.ndarray) -> np.ndarray:\n        """Total prediction: fast + beta*slow component."""\n        return self.model.predict(phi) + self._slow_part(phi)\n\n    def update(self, phi: np.ndarray, y: np.ndarray) -> np.ndarray:\n        """\n        Online update on the residual target.\n        The returned error is the TOTAL prediction error (fast+slow),\n        usable directly for evaluation.\n        """\n        residual_target = y - self._slow_part(phi)\n        e_total = self.model.update(phi, residual_target)\n\n        self._steps += 1\n        if self._steps % self.consolidate_every == 0:\n            self.consolidate(phi)\n        return e_total\n\n    def consolidate(self, phi_probe: np.ndarray = None):\n        """\n        W_slow += (1-gamma)/beta * W_fast ;  W_fast *= gamma ; inflate P.\n        If phi_probe is given, the continuity deviation is measured\n        (for testing).\n        """\n        W_fast = self.model.get_weights()\n\n        if phi_probe is not None:\n            before = (phi_probe @ W_fast\n                      + self.beta * (phi_probe @ self.W_slow))\n\n        self.W_slow += (1.0 - self.gamma) / self.beta * W_fast\n        self.model.set_weights(self.gamma * W_fast)\n\n        if self.p_inflate != 1.0:\n            self.model.inflate_P(self.p_inflate)\n\n        if phi_probe is not None:\n            after = (phi_probe @ self.model.get_weights()\n                     + self.beta * (phi_probe @ self.W_slow))\n            d = float(np.max(np.abs(before - after)))\n            self.max_discontinuity = max(self.max_discontinuity, d)\n\n        self.n_consolidations += 1\n'
_mkmod('memory', MEMORY_SRC)

MULTIHEAD_SRC = '"""\nAPIA 2.0 Research Prototype\nModule: multihead.py\nPurpose: closest competitor baseline — Bereska et al. (PMLR 2022)-style\n      competitive MULTI-READOUT-HEAD continual learning.\n\nMechanism (as in the literature):\n  - S independent readout heads (each a full RLS engine).\n  - Per step, an EMA prediction error is tracked for each head.\n  - Winner-take-all: the head with the lowest EMA error predicts\n    AND is the only one updated.\n  - PASSIVE protection: losing heads are never updated -> no\n    forgetting, but also no consolidation/transfer.\n\nKey differences from CTX (Related-Work comparison):\n  - Our system has a single shared W_fast + gated slow slots; here\n    there are S independent weight sets (memory cost S*P: 3x more\n    covariance memory).\n  - No active write-gating; no continuity-preserving analytic\n    transfer; no occupancy-oracle targeting.\n  - The gate selection uses the same EMA logic as ours (fair\n    comparison).\n"""\n\nimport numpy as np\n\n\nclass MultiHeadMemory:\n    """\n    S independent RLS heads; argmin-EMA wins and is updated.\n\n    :param model_factory: callable producing a fresh RLS engine\n    :param n_slots: number of heads\n    :param alpha_ema: head-error EMA coefficient (same as CTX: 0.01)\n    """\n\n    def __init__(self, model_factory, n_slots: int = 3,\n                 alpha_ema: float = 0.01, alloc_thresh=None,\n                 alpha_m2: float = 0.02, soft_predict: bool = False,\n                 eta: float = 2.0):\n        self.heads = [model_factory() for _ in range(n_slots)]\n        self.n_slots = n_slots\n        self.alpha_ema = alpha_ema\n        # C-attribution variant: on the prediction side, CTX\'s\n        # normalized soft gate (w ~ exp(-eta E/E_min)) instead of hard\n        # argmin. The update rule remains winner-only, as in Bereska.\n        self.soft_predict = soft_predict\n        self.eta = eta\n        # Channel-isolation ablation (multihead+alloc): if min E_i >\n        # alloc_thresh*m2 and a never-updated head exists, write to\n        # that head. Adds CTX\'s write-protection channel to the\n        # competitor architecture — isolates the channel missing from\n        # passive protection.\n        self.alloc_thresh = alloc_thresh\n        self.alpha_m2 = alpha_m2\n        self._m2 = 1.0\n        self.upd_counts = np.zeros(n_slots, dtype=int)\n        self.E = np.zeros(n_slots)\n        self.slot_log = []\n\n    def update(self, phi, y):\n        # CAUSAL ORDER: selection + reported prediction use E from\n        # history only; per-head errors vs the current y are folded\n        # into the EMA only AFTER the prediction is committed (the\n        # previous order leaked the current target into the gate).\n        head_errs = np.empty(self.n_slots)\n        for i, h in enumerate(self.heads):\n            e_i = y - h.predict(phi)\n            head_errs[i] = float(np.sum(e_i * e_i))\n        # The reported error must be the actual prediction error: in\n        # soft_predict the mixture (pre-update, causal), in hard mode\n        # the winner\'s.\n        e_rep = (y - self.predict(phi)) if self.soft_predict else None\n        self._m2 = ((1 - self.alpha_m2) * self._m2\n                    + self.alpha_m2 * float(np.sum(y * y)))\n        k = int(np.argmin(self.E))\n        if (self.alloc_thresh is not None\n                and self.upd_counts.min() == 0\n                and self.E[k] > self.alloc_thresh * self._m2):\n            k = int(np.argmin(self.upd_counts))\n        self.slot_log.append(k)\n        self.upd_counts[k] += 1\n        ret = self.heads[k].update(phi, y)\n        self.E = ((1 - self.alpha_ema) * self.E\n                  + self.alpha_ema * head_errs)\n        return e_rep if e_rep is not None else ret\n\n    def predict(self, phi):\n        if not self.soft_predict:\n            return self.heads[int(np.argmin(self.E))].predict(phi)\n        e_min = max(self.E.min(), 1e-8)\n        z = -self.eta * self.E / e_min\n        z -= z.max()\n        w = np.exp(z)\n        w /= w.sum()\n        preds = np.stack([h.predict(phi) for h in self.heads])\n        return w @ preds\n'
_mkmod('multihead', MULTIHEAD_SRC)

CONTEXTUAL_MEMORY_SRC = '"""\nAPIA 2.0 Research Prototype\nModule: contextual_memory.py\nPurpose: N-slot contextual memory (context-gated memory).\n\nMotivation (from the failure of memory.py):\n    Unconditional consolidation moved forgetting into W_slow because\n    the transfer was regime-agnostic. Fix: each slot represents a\n    context, and consolidation writes ONLY to the active slot the\n    gate is confident about.\n\nPrediction model (soft gate):\n      y_hat = phi\'W_fast + beta * phi\' * (sum_i w_i * W_slow_i)\n      w_i   = softmax(-eta * E_i / (E_min + eps))\n\n      E_i : slow EMA error of slot i (context-match measure).\n      Ratioing by E_min -> scale-free hard discrimination.\n      An empty slot (W_slow=0) returns the residual error -> new\n      regimes naturally flow toward empty slots.\n\nConsolidation (correct slot semantics, bounded jump):\n      W_slow_k <- W_slow_k + (1-gamma)/beta * W_fast\n      W_fast   <- gamma * W_fast\n\n      Each slot represents its context INDEPENDENTLY (when w_k=1 its\n      contribution has the correct magnitude). For w_k<1 the jump is\n      bounded by (1-w_k)(1-gamma)|phi\'W_fast|; when the gate is\n      confident (w_k~1) the jump goes to ~0. The (1-gamma)/(beta*w_k)\n      rule was deliberately NOT used: it preserves instantaneous\n      continuity but overcharges the slot at w<1 and induces gate\n      oscillation.\n\nContamination protection:\n      Consolidation fires only when the period arrives AND the\n      short-term total error e_fast < e_gate*signal_var. Transition\n      window = high error = writing stops -> gives the gate time to\n      identify the true context. Target = argmin E; empty slots tie\n      on error, lowest index wins (bootstrap starts at slot 0).\n"""\n\nimport numpy as np\n\n\nclass ContextualMemory:\n    def __init__(self, model, n_slots: int = 3, beta: float = 1.0,\n                 gamma: float = 0.1, eta: float = 2.0,\n                 alpha_ema: float = 0.01, alpha_fast: float = 0.1,\n                 consolidate_every: int = 250, e_gate: float = 0.5,\n                 signal_var: float = 1.0, tau: float = 0.5,\n                 p_inflate: float = 1.5, eps: float = 1e-8,\n                 alpha_m2: float = 0.02,\n                 err_mode: str = \'slow\', write_protect: bool = True,\n                 empty_rule: str = \'count\',\n                 saturation: str = \'overwrite\',\n                 w_fast_cap: float = None):\n        """\n        :param model: RLS engine with get_weights/set_weights/inflate_P\n        :param n_slots: number of context slots (fixed)\n        :param beta: gain of W_slow\'s contribution to prediction\n        :param gamma: fraction of W_fast retained at consolidation\n        :param eta: gate sharpness (applied to the E/E_min ratio)\n        :param alpha_ema: slot-error EMA coefficient (for gate, slow)\n        :param alpha_fast: total-error EMA coefficient (for trigger, fast)\n        :param consolidate_every: consolidation period (steps)\n        :param e_gate: max fast error allowing consolidation\n                       (as a multiple of signal_var)\n        :param signal_var: initial prior estimate of E[y^2] (in place\n               of a non-causal global variance; overwritten by the\n               online estimate within ~1/alpha_m2 steps)\n        :param alpha_m2: E[y^2] EMA coefficient (signal-energy measure)\n        :param p_inflate: P inflation factor at consolidation\n        """\n        self.model = model\n        self.n_slots = n_slots\n        self.beta, self.gamma = beta, gamma\n        self.eta = eta\n        self.alpha_ema, self.alpha_fast = alpha_ema, alpha_fast\n        self.consolidate_every = consolidate_every\n        self.e_gate = e_gate\n        # CAUSALITY: thresholds use the online E[y^2] estimate instead\n        # of var(y). The empty-slot floor is E[y^2] anyway (M4); for\n        # zero-mean signals E[y^2]=var(y), so behavior matches earlier\n        # results. The initial value is a non-informative prior\n        # estimate; no future data is used.\n        self.alpha_m2 = alpha_m2\n        self._m2 = float(signal_var)\n        # Context-aware target threshold: E_k < tau*var => reinforce;\n        # otherwise write to the emptiest slot (contamination\n        # protection).\n        self.tau = tau\n        self.p_inflate = p_inflate\n        self.eps = eps\n        # Ablation flags (for Fig5 / Table 3):\n        #   err_mode=\'total\' -> v1 self-masking: slot error includes W_fast\n        #   write_protect=False -> blind argmin target without tau*var gate\n        #   empty_rule=\'norm\' -> v2: ||W_slow|| argmin (faulty occupancy proxy)\n        self.err_mode = err_mode\n        self.write_protect = write_protect\n        self.empty_rule = empty_rule\n        # Saturation policy (when ALL slots are populated and NEW_CTX\n        # arrives):\n        #   \'overwrite\' -> write over argmin c_i (least-consolidated);\n        #                  occupancy-weighted eviction, tends to\n        #                  protect the oldest/strongest context but\n        #                  gives NO guarantee.\n        #   \'refuse\'    -> refuse the write; all stored contexts are\n        #                  preserved, the new regime lives only in\n        #                  W_fast (memoryless).\n        self.saturation = saturation\n        # Valve-isolation ablation: refuse + norm-clamp. None = off.\n        # Non-consolidation drainage of W_fast — controls the bloat on\n        # its own; does NOT touch transfer/consolidation behavior.\n        self.w_fast_cap = w_fast_cap\n\n        W0 = model.get_weights()                       # (F, m)\n        self.W_slow = np.zeros((n_slots,) + W0.shape)  # (S, F, m)\n        self.E = np.zeros(n_slots)                     # slot EMA errors\n        self._e_fast = 0.0                             # total fast error\n        self._steps = 0\n        self.n_consolidations = 0\n        self.max_discontinuity = 0.0\n        self.slot_log = []                             # gate argmax history\n        self.gate_log = []                             # gate weight vector (S,) history\n        self.cons_log = []                             # (step, slot, mode) history\n        # Occupancy proxy: count, not norm. Regime weight norms are\n        # incomparable; how many consolidations a slot received is\n        # neutral and comparable.\n        self.slot_cons_counts = np.zeros(n_slots, dtype=int)\n\n    # ---------- internal helpers ----------\n    def _slot_errors(self, phi, y):\n        """\n        Context-match error: e_i = ||y - beta*phi\'W_slow_i||^2 -> (S,)\n\n        Deliberately EXCLUDES W_fast: W_fast learns to compensate for\n        the active slot\'s contribution (self-masking) and masks slot\n        quality -> the gate locks up. The pure slow-memory error is\n        both a context detector and an empty-slot detector (empty:\n        e = var(y)).\n        """\n        slow = np.einsum(\'f,sfm->sm\', phi, self.W_slow)   # (S,m)\n        if self.err_mode == \'total\':\n            # v1 ablation: include the W_fast prediction (self-masking).\n            slow = slow + (phi @ self.model.get_weights())[None, :] / self.beta\n        return np.sum((y[None, :] - self.beta * slow) ** 2, axis=1)\n\n    def _gate(self):\n        """w_i ∝ exp(-eta * E_i/(E_min+eps)); (S,) weights."""\n        e_min = max(self.E.min(), self.eps)\n        z = -self.eta * self.E / e_min\n        z -= z.max()  # numerical safety\n        w = np.exp(z)\n        return w / w.sum()\n\n    def _slow_mix(self, phi, w):\n        """beta * phi\' * (sum_i w_i W_slow_i) -> (m,)"""\n        W_mix = np.einsum(\'s,sfm->fm\', w, self.W_slow)\n        return self.beta * (phi @ W_mix)\n\n    # ---------- main interface ----------\n    def predict(self, phi):\n        return self.model.predict(phi) + self._slow_mix(phi, self._gate())\n\n    def update(self, phi, y):\n        # 1) CAUSAL ORDER: the gate must be computed from slot-error\n        #    statistics that exclude the current target. _slot_errors is\n        #    evaluated now (same values it would have anywhere in this\n        #    step: err_mode=\'slow\' reads W_slow only; \'total\' reads\n        #    pre-update W_fast) but folded into E only AFTER the\n        #    prediction is issued — otherwise w would depend on y.\n        slot_errs = self._slot_errors(phi, y)\n\n        # 2) Gate on stale E, then update W_fast on the GATED residual\n        w = self._gate()\n        residual = y - self._slow_mix(phi, w)\n        e_total = self.model.update(phi, residual)\n\n        # 3) Now that the prediction is committed, fold the observed\n        #    context-match errors into the slot EMA.\n        self.E = ((1 - self.alpha_ema) * self.E\n                  + self.alpha_ema * slot_errs)\n\n        # 3) Fast EMA for the trigger + online E[y^2] for signal energy\n        e_now = float(np.sum(e_total ** 2))\n        self._e_fast = ((1 - self.alpha_fast) * self._e_fast\n                        + self.alpha_fast * e_now)\n        self._m2 = ((1 - self.alpha_m2) * self._m2\n                    + self.alpha_m2 * float(np.sum(y * y)))\n        # Single-variable intervention: norm-clamp (independent of\n        # consolidation)\n        if self.w_fast_cap is not None:\n            wf = self.model.get_weights()\n            n = float(np.linalg.norm(wf))\n            if n > self.w_fast_cap:\n                self.model.set_weights(wf * (self.w_fast_cap / n))\n\n        # 4) Periodic + stable + CONTEXT-AWARE consolidation.\n        #    E_min < tau*var  -> REINFORCE: write to argmin slot\n        #    otherwise        -> NEW CONTEXT: write to the emptiest\n        #                        slot. Never write to a populated\n        #                        high-error slot -> contamination\n        #                        stops (slot-poisoning fix).\n        self._steps += 1\n        self.slot_log.append(int(np.argmax(w)))\n        self.gate_log.append(w.copy())\n        if (self._steps % self.consolidate_every == 0\n                and self._e_fast <= self.e_gate * self._m2):\n            k = int(np.argmin(self.E))\n            if not self.write_protect or self.E[k] < self.tau * self._m2:\n                target, mode = k, 0            # REINFORCE (v1: blind argmin)\n            elif self.empty_rule == \'count\':\n                # Emptiest slot = slot with fewest consolidations.\n                # The invariant "never write to a populated slot" is\n                # only defined while an empty slot exists: at\n                # saturation, \'refuse\' skips the write, \'overwrite\'\n                # evicts the least-consolidated context (mode=3).\n                if (self.slot_cons_counts.min() > 0\n                        and self.saturation == \'refuse\'):\n                    target, mode = -1, 2\n                else:\n                    target = int(np.argmin(self.slot_cons_counts))\n                    mode = 1 if self.slot_cons_counts[target] == 0 else 3\n            else:\n                # v2 ablation: norm-based occupancy (faulty proxy)\n                norms = np.linalg.norm(\n                    self.W_slow.reshape(self.n_slots, -1), axis=1)\n                target, mode = int(np.argmin(norms)), 1\n            if target >= 0:\n                self.consolidate(phi, target)\n            self.cons_log.append((self._steps, target, mode))\n        return e_total\n\n    def consolidate(self, phi_probe, k):\n        """Inject (1-gamma)/beta * W_fast into slot k, decay W_fast."""\n        W_fast = self.model.get_weights()\n        before = self.predict(phi_probe)\n\n        self.W_slow[k] += (1.0 - self.gamma) / self.beta * W_fast\n        self.model.set_weights(self.gamma * W_fast)\n        if self.p_inflate != 1.0:\n            self.model.inflate_P(self.p_inflate)\n\n        d = float(np.max(np.abs(before - self.predict(phi_probe))))\n        self.max_discontinuity = max(self.max_discontinuity, d)\n        self.n_consolidations += 1\n        self.slot_cons_counts[k] += 1\n'
_mkmod('contextual_memory', CONTEXTUAL_MEMORY_SRC)

CONTINUAL_PROTOCOL_SRC = '"""\nAPIA 2.0 Research Prototype\nModule: continual_protocol.py\nPurpose: test of the "no-forgetting" claim — sine -> square -> sine\nregime change.\n\nComparison (all with lambda=0.98, P-bounding active via\nwindup_mult=1e4):\n  (a) FullRLS+bound : does P-bounding rescue full RLS? (ablation)\n  (b) BlockRLS+bound: memoryless reference — does it relearn sine\n      from scratch on return?\n  (c) BlockRLS+mem  : DualMemory (gamma=0.1, consolidation every 250 steps)\n\nPrimary metric: phase-3 (sine return) "onset" NMSE (first 250 steps).\n  If memory helps, (c)\'s onset error should be clearly lower than (b)\'s.\nSecondary: phase-end NMSEs + consolidation continuity deviation\n  (should be ~0).\n"""\n\nimport numpy as np\n\nfrom reservoir import ReservoirEngine\nfrom rls_engine import SplineFeatureMap, FullRLS, BlockDiagRLS\nfrom memory import DualMemory\nfrom contextual_memory import ContextualMemory\nfrom multihead import MultiHeadMemory\n\n# ---------------- Protocol constants ----------------\nSEEDS = 10\nD, K = 100, 10\nWASHOUT = 500\nPHASE_LEN = 1500\nPHASES = ["sine", "square", "sine"]     # sine -> square -> sine\nPERIOD = 80.0\nLAM = 0.98\nINIT_VAR = 1e2\nWINDUP_MULT = 1e4\nWINDOW = 250                          # onset / end measurement window\n\nMEM_BETA = 1.0\nMEM_GAMMA = 0.1\nMEM_CONS_EVERY = 250\nMEM_P_INFLATE = 1.5\n\nTOTAL = WASHOUT + PHASE_LEN * len(PHASES)\n\n\ndef waveform(task: str, t: float) -> float:\n    s = np.sin(2.0 * np.pi * t / PERIOD)\n    if task == "square":\n        return float(np.sign(s))\n    if task == "triangle":\n        return float(2.0 * np.abs(2.0 * ((t / PERIOD) % 1.0)) - 1.0)\n    return s\n\n\ndef build_stream(seed, phases=None, phase_len=None):\n    """Different waveform per phase -> u(t); target u(t+1)."""\n    phases = PHASES if phases is None else phases\n    phase_len = PHASE_LEN if phase_len is None else phase_len\n    total = WASHOUT + phase_len * len(phases)\n    u = np.zeros(total)\n    for t in range(total):\n        if t < WASHOUT:\n            u[t] = np.sin(2.0 * np.pi * t / PERIOD)\n        else:\n            ph = phases[(t - WASHOUT) // phase_len]\n            u[t] = waveform(ph, t - WASHOUT)\n    mu, sd = u.mean(), u.std()\n    u = (u - mu) / sd\n    # np.roll wrap artifact: to avoid y[-1] = u[0], generate the last\n    # sample as the continuation of the final phase (standardized).\n    nxt = (waveform(phases[-1], total - WASHOUT) - mu) / sd\n    y = np.empty(total)\n    y[:-1] = u[1:]\n    y[-1] = nxt\n    return u, y\n\n\ndef make_stream_states(u_all, seed, fmap):\n    """Generate the reservoir/data stream once, shared by all methods."""\n    total = len(u_all)\n    res = ReservoirEngine(1, D, 0.1, 0.3, 0.8, seed=seed)\n    Phi = np.empty((total - WASHOUT, fmap.n_features))\n    for t in range(total):\n        x = res.step(np.array([u_all[t]]))\n        if t >= WASHOUT:\n            Phi[t - WASHOUT] = fmap.transform(x)\n    return Phi\n\n\ndef run_method(kind, Phi, Y, sig_var):\n    """kind in {\'full\',\'block\',\'blockmem\',\'ctxmem\'} -> per-step error series."""\n    F = D * K + 1\n    if kind == \'multihead\':\n        model = MultiHeadMemory(\n            lambda: BlockDiagRLS(D, K, 1, forgetting=LAM,\n                                 init_var=INIT_VAR,\n                                 windup_mult=WINDUP_MULT),\n            n_slots=3)\n        upd = model.update\n    elif kind == \'full\':\n        model = FullRLS(F, 1, forgetting=LAM, init_var=INIT_VAR,\n                        windup_mult=WINDUP_MULT)\n        upd = model.update\n    elif kind == \'block\':\n        model = BlockDiagRLS(D, K, 1, forgetting=LAM, init_var=INIT_VAR,\n                             windup_mult=WINDUP_MULT)\n        upd = model.update\n    elif kind == \'blockmem\':\n        base = BlockDiagRLS(D, K, 1, forgetting=LAM, init_var=INIT_VAR,\n                            windup_mult=WINDUP_MULT)\n        model = DualMemory(base, beta=MEM_BETA, gamma=MEM_GAMMA,\n                           consolidate_every=MEM_CONS_EVERY,\n                           p_inflate=MEM_P_INFLATE)\n        upd = model.update\n    else:  # ctxmem\n        base = BlockDiagRLS(D, K, 1, forgetting=LAM, init_var=INIT_VAR,\n                            windup_mult=WINDUP_MULT)\n        model = ContextualMemory(base, n_slots=3, beta=MEM_BETA,\n                                 gamma=MEM_GAMMA, eta=2.0,\n                                 consolidate_every=MEM_CONS_EVERY,\n                                 e_gate=0.5,\n                                 p_inflate=MEM_P_INFLATE)\n        upd = model.update\n\n    errs = np.empty(Phi.shape[0])\n    for i in range(Phi.shape[0]):\n        e = upd(Phi[i], Y[i])\n        errs[i] = float(np.sum(e ** 2))\n    return errs, model\n\n\ndef window_nmse(errs, y, lo, hi):\n    """Mean e^2 in the window / full-series variance (cross-phase compare)."""\n    return float(np.mean(errs[lo:hi]) / np.var(y))\n\n\ndef main():\n    fmap = SplineFeatureMap(D, K, 3)\n    methods = [\'full\', \'block\', \'blockmem\', \'multihead\', \'ctxmem\']\n    labels = {\'full\': \'FullRLS+bound\', \'block\': \'BlockRLS+bound\',\n              \'blockmem\': \'BlockRLS+naive\', \'multihead\': \'MultiHead\',\n              \'ctxmem\': \'BlockRLS+CTX\'}\n\n    # metric[method][phase][metric] = [seed values]\n    met = {m: {p: {\'onset\': [], \'end\': []} for p in range(3)}\n           for m in methods}\n    disc = {m: [] for m in (\'blockmem\', \'ctxmem\')}\n    slot_reports = []\n\n    for seed in range(SEEDS):\n        u_all, y_all = build_stream(seed)\n        Phi = make_stream_states(u_all, seed, fmap)\n        Y = y_all[WASHOUT:].reshape(-1, 1)\n        sig_var = float(np.var(y_all))\n        print(f"seed {seed}: stream ready ({TOTAL} steps)")\n\n        for m in methods:\n            errs, model = run_method(m, Phi, Y, sig_var)\n            for p in range(3):\n                lo, hi = p * PHASE_LEN, (p + 1) * PHASE_LEN\n                met[m][p][\'onset\'].append(\n                    window_nmse(errs, y_all, lo, lo + WINDOW))\n                met[m][p][\'end\'].append(\n                    window_nmse(errs, y_all, hi - WINDOW, hi))\n            if m in disc:\n                disc[m].append(model.max_discontinuity)\n            if m == \'ctxmem\':\n                # Which slot won in which phase? (diagnostic)\n                log = np.array(model.slot_log)\n                rep = [int(np.bincount(log[p*PHASE_LEN:(p+1)*PHASE_LEN],\n                                       minlength=3).argmax())\n                       for p in range(3)]\n                slot_reports.append(rep)\n                print(f"  {labels[m]:<15}: P3 onset NMSE = "\n                      f"{met[m][2][\'onset\'][-1]:.3e} | slots(P1/2/3)={rep}"\n                      f" | consolidations={model.n_consolidations}")\n            else:\n                print(f"  {labels[m]:<15}: P3 onset NMSE = "\n                      f"{met[m][2][\'onset\'][-1]:.3e}")\n\n    # ---------------- Report ----------------\n    print("\\n" + "=" * 78)\n    print("SINE -> SQUARE -> SINE: window NMSE (mean +/- std, 10 seeds)")\n    print("=" * 78)\n    print(f"{\'Method\':<15} | {\'F1-sine onset\':<14} | {\'F1-sine end\':<14} | "\n          f"{\'F2-sq end\':<14} | {\'F3-sine ONSET\':<14} | {\'F3-sine end\':<14}")\n    print("-" * 78)\n    for m in methods:\n        def f(p, k):\n            v = met[m][p][k]\n            return f"{np.mean(v):.2e}+/-{np.std(v):.0e}"\n        print(f"{labels[m]:<15} | {f(0,\'onset\'):<14} | {f(0,\'end\'):<14} | "\n              f"{f(1,\'end\'):<14} | {f(2,\'onset\'):<14} | {f(2,\'end\'):<14}")\n    print("-" * 78)\n    for m in disc:\n        print(f"{labels[m]} continuity deviation (max, ~0 expected): "\n              f"{max(disc[m]):.2e}")\n    # Key claim: ctxmem\'s F3 onset advantage (vs both bare block and naive)\n    base = np.mean(met[\'block\'][2][\'onset\'])\n    naive = np.mean(met[\'blockmem\'][2][\'onset\'])\n    ctx = np.mean(met[\'ctxmem\'][2][\'onset\'])\n    print(f"-> F3 onset: block={base:.3e} | naive={naive:.3e} | "\n          f"ctx={ctx:.3e}")\n    print(f"-> CTX advantage vs block: x{base/max(ctx,1e-12):.2f} | "\n          f"vs naive: x{naive/max(ctx,1e-12):.2f}")\n    print("=" * 78)\n\n\n'
_mkmod('continual_protocol', CONTINUAL_PROTOCOL_SRC)


# ============ test drivers (isolated namespaces) ============
SATURATION_TEST_SRC = '"""\nAPIA 2.0 - Saturation-policy mini-ablation\n==============================================================\n4 regimes: sine -> square -> triangle -> sine  (S in {2,3}).\n\nScenario: square-phase fragmentation at S=3 + a triangle phase = a\nNEW context arrives while all slots are populated. Policy:\n  \'overwrite\' -> writes over argmin c_i (least-consolidated).\n  \'refuse\'    -> refuses the write; stored contexts are preserved.\n\nPrimary measure: F4-onset NMSE (sine return, first 250 steps) — did\nthe stored sine memory survive past saturation?\nSecondary: eviction (mode=3) / refusal (mode=2) counters.\n"""\n\nimport numpy as np\n\nfrom rls_engine import SplineFeatureMap, BlockDiagRLS\nfrom contextual_memory import ContextualMemory\nfrom continual_protocol import (build_stream, make_stream_states,\n                                D, K, WASHOUT, LAM, INIT_VAR,\n                                WINDUP_MULT, WINDOW)\n\nSEEDS = 10\nPHASES = [\'sine\', \'square\', \'triangle\', \'sine\']\nPH_LEN = 1500\nT_POST = PH_LEN * len(PHASES)\n\n\ndef make_model(kind):\n    base = lambda: BlockDiagRLS(D, K, 1, forgetting=LAM,\n                                init_var=INIT_VAR,\n                                windup_mult=WINDUP_MULT)\n    if kind == \'block\':\n        return base()\n    S, pol = kind[0], kind[1]      # \'2o\', \'2r\', \'3o\', \'3r\'\n    return ContextualMemory(base(), n_slots=int(S), beta=1.0,\n                            gamma=0.1, eta=2.0,\n                            consolidate_every=250, e_gate=0.5,\n                            p_inflate=1.5,\n                            saturation=\'refuse\' if pol == \'r\'\n                            else \'overwrite\')\n\n\ndef run(kind, Phi, Y):\n    m = make_model(kind)\n    errs = np.empty(len(Phi))\n    for i in range(len(Phi)):\n        errs[i] = float(np.sum(m.update(Phi[i], Y[i]) ** 2))\n    return errs, m\n\n\ndef main():\n    kinds = [\'block\', \'2o\', \'2r\', \'3o\', \'3r\']\n    labels = {\'block\': \'Block-RLS\', \'2o\': \'S=2 overwrite\',\n              \'2r\': \'S=2 refuse\', \'3o\': \'S=3 overwrite\',\n              \'3r\': \'S=3 refuse\'}\n    onset, evict, refuse_n = {k: [] for k in kinds}, \\\n                             {k: [] for k in kinds[1:]}, \\\n                             {k: [] for k in kinds[1:]}\n    fmap = SplineFeatureMap(D, K, 3)\n\n    for seed in range(SEEDS):\n        u_all, y_all = build_stream(seed, phases=PHASES,\n                                    phase_len=PH_LEN)\n        sig_var = float(np.var(y_all))\n        Phi = make_stream_states(u_all, seed, fmap)\n        Y = y_all[WASHOUT:].reshape(-1, 1)\n        lo = 3 * PH_LEN\n        for k in kinds:\n            errs, m = run(k, Phi, Y)\n            onset[k].append(float(np.mean(errs[lo:lo + WINDOW])\n                                  / sig_var))\n            if k != \'block\':\n                log = np.array([(t, s, mo) for t, s, mo\n                                in m.cons_log])\n                evict[k].append(int((log[:, 2] == 3).sum()))\n                refuse_n[k].append(int((log[:, 2] == 2).sum()))\n        print(f"seed {seed}: " + " | ".join(\n            f"{k}={onset[k][-1]:.3f}" for k in kinds))\n\n    print("\\n" + "=" * 70)\n    print("SATURATION TEST: F4-onset NMSE (sine return, 10 seeds)")\n    print("=" * 70)\n    for k in kinds:\n        v = np.array(onset[k])\n        line = f"{labels[k]:<15}: {v.mean():.4f} +/- {v.std():.4f}"\n        if k != \'block\':\n            line += (f"  | evict={np.mean(evict[k]):.1f}"\n                     f"  refuse={np.mean(refuse_n[k]):.1f}")\n        print(line)\n    print("-" * 70)\n    b = np.mean(onset[\'block\'])\n    for k in kinds[1:]:\n        print(f"{labels[k]}: vs block x{b / np.mean(onset[k]):.2f}")\n\n    np.savez(\'saturation_data.npz\',\n             **{f\'onset_{k}\': np.array(onset[k]) for k in kinds},\n             **{f\'evict_{k}\': np.array(evict[k]) for k in kinds[1:]},\n             **{f\'refuse_{k}\': np.array(refuse_n[k])\n                for k in kinds[1:]})\n    print("Saved: saturation_data.npz")\n\n\nif __name__ == \'__main__\':\n    main()\n'
VALVE_TEST_SRC = '"""\nAPIA 2.0 - Valve (pressure-release) confound test + Fig6\n==============================================================\nThe open question left by the B finding: does the F4 gain come from\nthe stored context, or from the gamma-decay drainage of W_fast\n(implicit regularization)?\n\nTwo tests:\n  1) CORRELATION: ||W_fast|| at the phase-4 boundary vs F4-onset\n     NMSE per run (all config x seed points).\n  2) INTERVENTION: refuse + norm-clamp (w_fast_cap=R). If recall\n     returns, the cause is MAGNITUDE; if not, it is STORAGE.\n     R = the median ||W_fast|| of the overwrite run.\n\nFig6: top panel ||W_fast||(t) refuse vs overwrite (log);\n      bottom panel rolling NMSE (phase-4 return window highlighted).\n"""\n\nimport numpy as np\nimport matplotlib\nmatplotlib.use(\'Agg\')\nimport matplotlib.pyplot as plt\nfrom scipy import stats\n\nfrom rls_engine import SplineFeatureMap, BlockDiagRLS\nfrom contextual_memory import ContextualMemory\nfrom continual_protocol import (build_stream, make_stream_states,\n                                D, K, WASHOUT, LAM, INIT_VAR,\n                                WINDUP_MULT, WINDOW)\n\nSEEDS = 10\nPHASES = [\'sine\', \'square\', \'triangle\', \'sine\']\nPL = 1500\n\n\ndef make_model(cfg, cap=None):\n    base = BlockDiagRLS(D, K, 1, forgetting=LAM, init_var=INIT_VAR,\n                        windup_mult=WINDUP_MULT)\n    if cfg == \'block\':\n        return base\n    sat = {\'o\': \'overwrite\', \'r\': \'refuse\', \'rc\': \'refuse\'}[cfg[0]]\n    return ContextualMemory(base, n_slots=2, beta=1.0, gamma=0.1,\n                            eta=2.0, consolidate_every=250,\n                            e_gate=0.5, p_inflate=1.5,\n                            saturation=sat, w_fast_cap=cap)\n\n\ndef _wnorm(m):\n    w = m.model.get_weights() if hasattr(m, \'model\') else m.get_weights()\n    return float(np.linalg.norm(w))\n\n\ndef run(cfg, Phi, Y, cap=None, log_norm=False):\n    m = make_model(cfg, cap)\n    errs = np.empty(len(Phi))\n    norms = np.empty(len(Phi)) if log_norm else None\n    for i in range(len(Phi)):\n        errs[i] = float(np.sum(m.update(Phi[i], Y[i]) ** 2))\n        if log_norm:\n            norms[i] = _wnorm(m)\n    return errs, m, norms\n\n\ndef main():\n    # --- 1) R calibration: overwrite median norm (seed 0) ---\n    fmap = SplineFeatureMap(D, K, 3)\n    u_all, y_all = build_stream(0, phases=PHASES, phase_len=PL)\n    Phi0 = make_stream_states(u_all, 0, fmap)\n    Y0 = y_all[WASHOUT:].reshape(-1, 1)\n    _, _, norms_o = run(\'o\', Phi0, Y0, log_norm=True)\n    R = float(np.median(norms_o[PL:]))          # median after phase 1\n    print(f"R (overwrite median ||W_fast||, P1+): {R:.3f}")\n\n    # --- 2) All configs: onset + boundary norm + phase-ends ---\n    cfgs = [\'block\', \'o\', \'r\', \'rc\']\n    onset = {c: [] for c in cfgs}\n    norm_b = {c: [] for c in cfgs}   # ||W_fast|| @ P4 boundary (t=3PL)\n    end_err = {c: {p: [] for p in range(4)} for c in cfgs}\n    for seed in range(SEEDS):\n        u_all, y_all = build_stream(seed, phases=PHASES, phase_len=PL)\n        sv = float(np.var(y_all))\n        Phi = make_stream_states(u_all, seed, fmap)\n        Y = y_all[WASHOUT:].reshape(-1, 1)\n        for c in cfgs:\n            errs, m, nr = run(c, Phi, Y, cap=R if c == \'rc\' else None,\n                              log_norm=True)\n            onset[c].append(float(np.mean(errs[3 * PL:3 * PL + WINDOW])\n                                  / sv))\n            norm_b[c].append(nr[3 * PL - 1])   # norm at P4 boundary\n            for p in range(4):\n                end_err[c][p].append(\n                    float(np.mean(errs[(p + 1) * PL - WINDOW:(p + 1) * PL])\n                          / sv))\n        print(f"seed {seed}: " + " | ".join(\n            f"{c}={onset[c][-1]:.3f}" for c in cfgs))\n\n    print("\\n=== VALVE TEST ===")\n    for c in cfgs:\n        v = np.array(onset[c])\n        print(f"{c:>6}: F4-onset={v.mean():.4f}+/-{v.std():.4f} "\n              f"| ||W_fast||@boundary={np.mean(norm_b[c]):.2f}")\n\n    # --- correlation: norm@boundary vs onset (all points, log-norm) ---\n    xs, ys = [], []\n    for c in cfgs:\n        xs += list(np.log10(np.array(norm_b[c]) + 1e-12))\n        ys += list(onset[c])\n    r_pear, p_pear = stats.pearsonr(xs, ys)\n    r_spe, p_spe = stats.spearmanr(xs, ys)\n    print(f"correlation log10||W_fast|| vs F4-onset: "\n          f"pearson r={r_pear:.3f} (p={p_pear:.2e}), "\n          f"spearman rho={r_spe:.3f} (p={p_spe:.2e})")\n\n    # --- phase-end context (baseline\'s forgetting cost) ---\n    print("baseline phase-end NMSE:", [\n        f"{np.mean(end_err[\'block\'][p]):.3f}" for p in range(4)])\n\n    # --- 3) Fig6: seed-0 trajectories ---\n    _, _, n_r = run(\'r\', Phi0, Y0, log_norm=True)\n    _, _, n_rc = run(\'rc\', Phi0, Y0, cap=R, log_norm=True)\n    errs_o, _, _ = run(\'o\', Phi0, Y0)\n    errs_r, _, _ = run(\'r\', Phi0, Y0)\n    errs_rc, _, _ = run(\'rc\', Phi0, Y0, cap=R)\n\n    fig, (a1, a2) = plt.subplots(2, 1, figsize=(7.5, 5.5),\n                                 sharex=True,\n                                 gridspec_kw={\'height_ratios\': [2, 1]})\n    t = np.arange(len(norms_o))\n    a1.semilogy(t, norms_o, lw=1.4, color=\'#1f77b4\',\n                label=\'overwrite\')\n    a1.semilogy(t, n_r, lw=1.4, color=\'#d62728\', label=\'refuse\')\n    a1.semilogy(t, n_rc, lw=1.2, ls=\'--\', color=\'#2ca02c\',\n                label=\'refuse+clamp\')\n    a1.axhline(R, color=\'k\', ls=\':\', lw=1)\n    a1.text(len(t) * 0.62, R * 1.3, f\'clamp R={R:.2f}\', fontsize=8)\n    for x in (PL, 2 * PL, 3 * PL):\n        a1.axvline(x, color=\'k\', lw=0.8, alpha=0.5)\n    a1.set_ylabel(r\'$\\|W_{\\mathrm{fast}}\\|$\')\n    a1.legend(loc=\'upper left\', fontsize=8)\n    a1.set_title(\'Fast-weight magnitude: consolidation as drainage valve\')\n\n    roll = lambda e: (np.convolve(e, np.ones(100) / 100, \'valid\')\n                      / float(np.var(y_all)))\n    tt = np.arange(len(errs_o) - 99)\n    a2.semilogy(tt, roll(errs_o), lw=1.4, color=\'#1f77b4\')\n    a2.semilogy(tt, roll(errs_r), lw=1.4, color=\'#d62728\')\n    a2.semilogy(tt, roll(errs_rc), lw=1.2, ls=\'--\', color=\'#2ca02c\')\n    for x in (PL, 2 * PL, 3 * PL):\n        a2.axvline(x, color=\'k\', lw=0.8, alpha=0.5)\n    a2.set_xlabel(\'step $t$\')\n    a2.set_ylabel(\'rolling NMSE (w=100)\')\n    fig.tight_layout()\n    fig.savefig(\'fig6_valve.png\', dpi=300)\n    plt.close(fig)\n\n    np.savez(\'valve_data.npz\',\n             **{f\'onset_{c}\': np.array(onset[c]) for c in cfgs},\n             **{f\'normb_{c}\': np.array(norm_b[c]) for c in cfgs},\n             norms_overwrite=norms_o, norms_refuse=n_r,\n             norms_refuse_clamp=n_rc, R=R)\n    print("Saved: fig6_valve.png + valve_data.npz")\n\n\nif __name__ == \'__main__\':\n    main()\n'
CLAMP_CONTROL_SRC = '"""\nAPIA 2.0 - Main-protocol valve control + C-attribution variants\n=================================================================\n1) HEADLINE CONFOUND CONTROL: block+clamp on the main protocol\n   (sine>square>sine). R = median ||W_fast|| at ctx_v3\'s\n   consolidation events (pooled over 10 seeds) — protocol-specific,\n   a matched-norm control NOT tuned on the test.\n2) C-attribution: multihead+soft_predict (normalized gate only)\n   and mh_alloc+soft (alloc + soft gate) — whether the remaining\n   ~3.8x comes from gate quality or from transfer.\n3) Lossy-vs-lossless: F3-end error of the clamp variants —\n   prediction: clamp destroys information -> end-error worse than\n   CTX.\n"""\n\nimport numpy as np\nfrom scipy import stats\n\nfrom rls_engine import SplineFeatureMap, BlockDiagRLS\nfrom contextual_memory import ContextualMemory\nfrom multihead import MultiHeadMemory\nfrom continual_protocol import (build_stream, make_stream_states,\n                                D, K, WASHOUT, PHASE_LEN, LAM,\n                                INIT_VAR, WINDUP_MULT, WINDOW)\n\nSEEDS = 10\n\n\ndef ctx():\n    base = BlockDiagRLS(D, K, 1, forgetting=LAM, init_var=INIT_VAR,\n                        windup_mult=WINDUP_MULT)\n    return ContextualMemory(base, n_slots=3, beta=1.0, gamma=0.1,\n                            eta=2.0, consolidate_every=250,\n                            e_gate=0.5, p_inflate=1.5)\n\n\ndef mh(alloc, soft):\n    return MultiHeadMemory(\n        lambda: BlockDiagRLS(D, K, 1, forgetting=LAM,\n                             init_var=INIT_VAR,\n                             windup_mult=WINDUP_MULT),\n        n_slots=3, alloc_thresh=alloc, soft_predict=soft)\n\n\ndef run(m, Phi, Y, cap=None, log_wnorm_at_cons=False):\n    errs = np.empty(len(Phi))\n    cons_norms = []\n    prev_cons = 0\n    for i in range(len(Phi)):\n        errs[i] = float(np.sum(m.update(Phi[i], Y[i]) ** 2))\n        if cap is not None:\n            w = m.get_weights()\n            n = float(np.linalg.norm(w))\n            if n > cap:\n                m.set_weights(w * (cap / n))\n        if log_wnorm_at_cons and m.n_consolidations > prev_cons:\n            cons_norms.append(\n                float(np.linalg.norm(m.model.get_weights())))\n            prev_cons = m.n_consolidations\n    return errs, cons_norms\n\n\ndef main():\n    fmap = SplineFeatureMap(D, K, 3)\n    lo = 2 * PHASE_LEN\n\n    # --- 1) R calibration: ctx consolidation norms (10 seeds) ---\n    cons_norms = []\n    for seed in range(SEEDS):\n        u_all, y_all = build_stream(seed)\n        Phi = make_stream_states(u_all, seed, fmap)\n        Y = y_all[WASHOUT:].reshape(-1, 1)\n        m = ctx()\n        prev = 0\n        for i in range(len(Phi)):\n            m.update(Phi[i], Y[i])\n            if m.n_consolidations > prev:\n                cons_norms.append(\n                    float(np.linalg.norm(m.model.get_weights())))\n                prev = m.n_consolidations\n    R = float(np.median(cons_norms))\n    print(f"R (ctx consolidation median ||W_fast||, {len(cons_norms)} events)"\n          f": {R:.3f}")\n\n    # --- 2) Main protocol: block / block+clamp / ctx / mh variants ---\n    kinds = [\'block\', \'block_clamp\', \'ctx\', \'mh_soft\', \'mh_alloc_soft\']\n    ons = {k: [] for k in kinds}\n    end3 = {k: [] for k in kinds}\n    for seed in range(SEEDS):\n        u_all, y_all = build_stream(seed)\n        sv = float(np.var(y_all))\n        Phi = make_stream_states(u_all, seed, fmap)\n        Y = y_all[WASHOUT:].reshape(-1, 1)\n        for k in kinds:\n            if k == \'block\':\n                m = BlockDiagRLS(D, K, 1, forgetting=LAM,\n                                 init_var=INIT_VAR,\n                                 windup_mult=WINDUP_MULT)\n                errs, _ = run(m, Phi, Y)\n            elif k == \'block_clamp\':\n                m = BlockDiagRLS(D, K, 1, forgetting=LAM,\n                                 init_var=INIT_VAR,\n                                 windup_mult=WINDUP_MULT)\n                errs, _ = run(m, Phi, Y, cap=R)\n            elif k == \'ctx\':\n                errs, _ = run(ctx(), Phi, Y)\n            elif k == \'mh_soft\':\n                errs, _ = run(mh(None, True), Phi, Y)\n            else:\n                errs, _ = run(mh(0.5, True), Phi, Y)\n            ons[k].append(float(np.mean(errs[lo:lo + WINDOW]) / sv))\n            hi = 3 * PHASE_LEN\n            end3[k].append(float(np.mean(errs[hi - WINDOW:hi]) / sv))\n        print(f"seed {seed}: " + " | ".join(\n            f"{k}={ons[k][-1]:.3f}" for k in kinds))\n\n    print("\\n=== MAIN-PROTOCOL VALVE CONTROL ===")\n    for k in kinds:\n        v, e = np.array(ons[k]), np.array(end3[k])\n        print(f"{k:>14}: F3-onset={v.mean():.4f}+/-{v.std():.4f} "\n              f"| F3-end={e.mean():.2e}")\n    b, c = np.array(ons[\'block\']), np.array(ons[\'block_clamp\'])\n    w, p = stats.wilcoxon(b, c, alternative=\'greater\')\n    print(f"block vs block+clamp: W={w}, p={p:.4f} "\n          f"(one-sided); mean ratio x{b.mean()/c.mean():.2f}")\n    cc = np.array(ons[\'ctx\'])\n    w2, p2 = stats.wilcoxon(c, cc, alternative=\'greater\')\n    print(f"block+clamp vs ctx: W={w2}, p={p2:.4f} "\n          f"| remaining ratio x{c.mean()/cc.mean():.2f}")\n\n    import json\n    out = {\'R\': R, \'seeds\': SEEDS,\n           **{k: {\'onset_mean\': float(np.mean(ons[k])),\n                  \'onset_std\': float(np.std(ons[k])),\n                  \'f3_end_mean\': float(np.mean(end3[k])),\n                  \'per_seed\': [float(v) for v in ons[k]]}\n              for k in kinds}}\n    json.dump(out, open(\'clamp_control.json\', \'w\'), indent=2)\n    print("Saved: clamp_control.json")\n\n\nif __name__ == \'__main__\':\n    main()\n'

